sys_script_include.script:
var AESCommunicationArchive = Class.create();
AESCommunicationArchive.prototype = {
    initialize: function() {
        this.TABLE = 'x_733168_aes_communication';
        this.STATE_EXPIRED = 'expired';
    },

    /**
     * Archives an expired communication.
     * State remains Expired; active becomes false.
     */
    archive: function(source) {
        var communication = this._resolveCommunication(source);

        if (!communication)
            return this._failure('not_found');

        if (!this._isState(communication, this.STATE_EXPIRED))
            return this._failure('invalid_transition');

        if (communication.getValue('active') != '1')
            return this._failure('already_archived');

        communication.setValue('active', false);

        return this._update(communication);
    },

    calculateArchiveDate: function(expirationDate, archiveAfter, periodType) {
        var days = parseInt(archiveAfter, 10);

        if (gs.nil(expirationDate) || isNaN(days) || days <= 0)
            return null;

        var archiveDate = new GlideDateTime(expirationDate);

        if (periodType == 'days') {
            archiveDate.addDaysUTC(days);
            return archiveDate;
        }

        if (periodType == 'weekdays')
            return this._addWeekdays(archiveDate, days);

        return null;
    },

    _addWeekdays: function(date, days) {
        var result = new GlideDateTime(date);
        var added = 0;

        while (added < days) {
            result.addDaysUTC(1);

            var dayOfWeek = result.getDayOfWeekUTC();

            if (dayOfWeek != 6 && dayOfWeek != 7)
                added++;
        }

        return result;
    },

    _resolveCommunication: function(source) {
        if (gs.nil(source))
            return null;

        if (
            typeof source == 'object' &&
            typeof source.getTableName == 'function'
        ) {
            if (!source.isValidRecord())
                return null;

            return source;
        }

        var communication = new GlideRecord(this.TABLE);

        if (!communication.get(source))
            return null;

        return communication;
    },

    _isState: function(communication, state) {
        return communication.getValue('state') == state;
    },

    _update: function(communication) {
        var updatedId = communication.update();

        if (!updatedId)
            return this._failure('update_failed');

        return this._success();
    },

    _success: function() {
        return {
            success: true
        };
    },

    _failure: function(reason) {
        return {
            success: false,
            reason: reason
        };
    },

    type: 'AESCommunicationArchive'
};
